func (r *StatusRecorder) HeaderWritten() bool {
	return r.state.Load()&statusHeaderWritten != 0
}

func (r *StatusRecorder) Status() int {
	return int(r.state.Load() &^ statusHeaderWritten)
}

func (r *StatusRecorder) Write(body []byte) (int, error) {
	r.commitStatus(http.StatusOK)
	return r.ResponseWriter.Write(body)
}

func (r *StatusRecorder) WriteHeader(status int) {
	r.commitStatus(status)
	r.ResponseWriter.WriteHeader(status)
}

func (r *flushingStatusRecorder) Flush() {
	r.commitStatus(http.StatusOK)
	r.flusher.Flush()
}

func (w *tenantStatusWriter) WriteHeader(code int) {
	if w.wroteHeader {
		return
	}
	if isInterimStatus(code) {
		w.copyHeadersToTarget()
		w.target.WriteHeader(code)
		return
	}
	w.status = code
	w.wroteHeader = true
}

