func (o payrollMailOutbox) Enqueue(ctx context.Context, message workforce.PayrollMailMessage) (int64, error) {
	mail := email.Message{From: o.from, To: email.NewEmail(message.ToName, message.ToAddress), Subject: message.Subject, Template: message.Template, Content: payrollTemplateData(message.Content)}
	identity := email.ResolveReplyToIdentity(ctx, o.identity, message.TenantID, o.logger)
	mail.ReplyTo = email.NewEmail(identity.Name, identity.Address)
	enqueued, err := o.outbox.EnqueueMailIntent(ctx, DurableMail{IdempotencyKey: message.IdempotencyKey, TenantID: message.TenantID, Message: mail, Type: message.Type, ReferenceID: message.ReferenceID, ExpiresAt: message.ExpiresAt, MaxAttempts: message.MaxAttempts, Backoff: message.Backoff})
	return enqueued.ID, err
}

