func (a timetableActivityUpdates) AnnounceActivityUpdate(tenantID, activeGroupID int64, update timetable.TouchedActivity) error {
	activeGroupIDStr := strconv.FormatInt(activeGroupID, 10)
	instanceID := strconv.FormatInt(update.InstanceID, 10)
	instanceDate := update.Date.String()
	instanceStart := update.StartTime.Format("15:04:05")
	event := realtime.NewEvent(realtime.EventActivityUpdate, activeGroupIDStr, realtime.EventData{InstanceID: &instanceID, InstanceDate: &instanceDate, InstanceStartTime: &instanceStart})
	return a.broadcaster.BroadcastToGroup(tenantID, activeGroupIDStr, event)
}

func (a timetableAttendanceAnnouncer) AnnounceAttendanceChanged(tenantID, activeGroupID, instanceID int64) error {
	instance := strconv.FormatInt(instanceID, 10)
	reason := "timetable_attendance_updated"
	event := realtime.NewEvent(realtime.EventActiveSupervisionChanged, strconv.FormatInt(activeGroupID, 10), realtime.EventData{InstanceID: &instance, Reason: &reason})
	return a.broadcaster.BroadcastToTenant(tenantID, event)
}

